def figs(*pares):
    return [{"arquivo": a, "alt": t} for a, t in pares]


def X(n, materia, assunto, gab_expl, imagens=(), tags=(), pular=(), trocas=(), enun=None, alts=None):
    q = D[n]
    a = dict(alts or q["alternativas"])
    a = {k: v.replace(" CIÊNCIAS DA NATUREZA E SUAS TECNOLOGIAS", "").strip() for k, v in a.items()}
    return {"materia": materia, "assunto": assunto, "area": "Ciências Humanas", "tags": list(tags),
            "enunciado": enun or montar_enunciado(q, pular, trocas), "alternativas": a, "imagens": list(imagens), "explicacao": gab_expl}


